33	static void print_usage(void)
34	{
35	    printf("Usage: lvglsim [options]\n");
36	    printf("Options:\n");
37	    printf("  -b <backend>   Backend to use (SDL, WAYLAND, X11, DRM, FBDEV, GLFW)\n");
38	    printf("  -W <width>     Window width (default: 1920)\n");
39	    printf("  -H <height>    Window height (default: 1200)\n");
40	    printf("  -f             Fullscreen\n");
41	    printf("  -B             List supported backends\n");
42	    printf("  -h             Print this help\n");
43	    printf("\nExamples:\n");
44	    printf("  lvglsim -b SDL -W 1920 -H 1200\n");
45	}
46	
47	static void configure_simulator(int argc, char **argv)
48	{
49	    int opt;
50	    const char *backend = "SDL";
51	    int width = 1920, height = 1200;
52	    int fullscreen = 0;
53	
54	    while ((opt = getopt(argc, argv, "b:W:H:fhB")) != -1) {
55	        switch (opt) {
56	        case 'b':
57	            backend = optarg;
58	            break;
59	        case 'W':
60	            width = atoi(optarg);
61	            break;
62	        case 'H':
63	            height = atoi(optarg);
64	            break;
65	        case 'f':
66	            fullscreen = 1;
67	            break;
68	        case 'B':
69	            driver_backends_print_supported();
70	            exit(0);
71	        case 'h':
72	        default:
73	            print_usage();
74	            exit(0);
75	        }
76	    }
77	
78	    selected_backend = strdup(backend);
79	    settings.window_width = width;
80	    settings.window_height = height;
81	    settings.rotation = LV_DISPLAY_ROTATION_0;
82	    settings.fullscreen = fullscreen;
83	    settings.maximize = false;
84	}
85	
86	int main(int argc, char **argv)
87	{
88	    configure_simulator(argc, argv);
89	
90	    lv_init();
91	
92	    driver_backends_register();
93	
94	    if (driver_backends_init_backend(selected_backend) == -1)
95	        die("Failed to initialize display backend");
96	
97	    /* Build the same UI as the board (deskmate_ui.c) */
98	    deskmate_ui_create();
99	
100	    driver_backends_run_loop();
101	    return 0;
102	}

