int dm_weather_fetch(dm_weather_t *w)
{
    static char buf[4096];
    char dates[DM_WEATHER_DAYS][16];
    int codes[DM_WEATHER_DAYS]  = {0};
    int tmax[DM_WEATHER_DAYS]   = {0};
    int tmin[DM_WEATHER_DAYS]   = {0};
    int n, i;

    if (w == NULL)
        return -1;

    memset(w, 0, sizeof(*w));

    if (http_get(DM_W_PATH, buf, sizeof(buf)) < 0)
        return -1;

    /* Current weather */
    json_int(buf, "\"current_weather\"", NULL);         /* just check presence */
    if (strstr(buf, "\"current_weather\":") != NULL)
        {
            json_int(buf, "\"temperature\"", &w->cur_temp);
            json_int(buf, "\"weathercode\"", &w->cur_code);
        }

    /* Daily forecast */
    n = json_str_array(buf, "\"time\"", dates, DM_WEATHER_DAYS);
    if (n == 0)
        return -1;

    json_int_array(buf, "\"weather_code\"", codes, DM_WEATHER_DAYS);
    json_int_array(buf, "\"temperature_2m_max\"", tmax, DM_WEATHER_DAYS);
    json_int_array(buf, "\"temperature_2m_min\"", tmin, DM_WEATHER_DAYS);

    w->n_days = n;
    for (i = 0; i < n; i++)
        {
            strncpy(w->days[i].date, dates[i], sizeof(w->days[i].date) - 1);
            w->days[i].date[sizeof(w->days[i].date) - 1] = '\0';
            w->days[i].code  = codes[i];
            w->days[i].tmax  = tmax[i];
            w->days[i].tmin  = tmin[i];
            w->days[i].wday  = weekday_from_date(dates[i]);
        }

    return 0;
}

