/* WMO weather code → LV_SYMBOL glyph + accent color */
static const char *dm_wmo_symbol(int code)
{
    if (code == 0) return LV_SYMBOL_OK;                     /* clear */
    if (code >= 1 && code <= 3) return LV_SYMBOL_REFRESH;   /* cloudy */
    if (code == 45 || code == 48) return LV_SYMBOL_CLOSE;   /* fog */
    if (code >= 51 && code <= 82) return LV_SYMBOL_TINT;    /* rain */
    if (code >= 71 && code <= 86) return LV_SYMBOL_WARNING; /* snow */
    if (code >= 95) return LV_SYMBOL_CHARGE;                /* storm */
    return LV_SYMBOL_REFRESH;
}

static uint32_t dm_wmo_color(int code)
{
    if (code == 0) return 0xFF9500;         /* sunny orange */
    if (code >= 1 && code <= 3) return 0x8E8E93;    /* cloudy grey */
    if (code == 45 || code == 48) return 0x6B7280;  /* fog grey */
    if (code >= 51 && code <= 82) return 0x007AFF;  /* rain blue */
    if (code >= 71 && code <= 86) return 0x5AC8FA;  /* snow light blue */
    if (code >= 95) return 0xAF52DE;                /* storm purple */
    return 0x8E8E93;
}

/* iOS-style daily forecast: one row per day (weekday | icon | hi/lo) */
static void create_weather_card(lv_obj_t *card)
{
    static const char *wdays[] = { "Sun", "Mon", "Tue", "Wed",
                                   "Thu", "Fri", "Sat" };

    lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(card, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_START);
    lv_obj_set_style_pad_row(card, 2, 0);
    lv_obj_set_style_pad_all(card, 16, 0);

    /* Row 1: current temp (big) + description */
    lv_obj_t *top_row = make_clean_cont(card);
    lv_obj_set_size(top_row, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(top_row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(top_row, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

    w_cur_temp_lbl = lv_label_create(top_row);
    lv_label_set_text(w_cur_temp_lbl, "--\xc2\xb0""C");
    lv_obj_set_style_text_color(w_cur_temp_lbl, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_text_font(w_cur_temp_lbl, FONT_ICON, 0);

    w_cur_desc_lbl = lv_label_create(top_row);
    lv_label_set_text(w_cur_desc_lbl, "Loading...");
    lv_obj_set_style_text_color(w_cur_desc_lbl, lv_color_hex(COL_SEC), 0);
    lv_obj_set_style_text_font(w_cur_desc_lbl, FONT_LABEL, 0);

    /* Daily rows */
    for (int i = 0; i < DM_WEATHER_DAYS; i++) {
        lv_obj_t *row = make_clean_cont(card);
        lv_obj_set_size(row, lv_pct(100), LV_SIZE_CONTENT);
        lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_BETWEEN,
                              LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_set_style_pad_top(row, 10, 0);

        w_day_lbl[i] = lv_label_create(row);
        lv_label_set_text(w_day_lbl[i], wdays[i]);
        lv_obj_set_style_text_font(w_day_lbl[i], FONT_BODY, 0);
        lv_obj_set_style_text_color(w_day_lbl[i], lv_color_hex(COL_TEXT), 0);

        w_icon_lbl[i] = lv_label_create(row);
        lv_label_set_text(w_icon_lbl[i], LV_SYMBOL_REFRESH);
        lv_obj_set_style_text_font(w_icon_lbl[i], FONT_ICON, 0);
        lv_obj_set_style_text_color(w_icon_lbl[i], lv_color_hex(COL_BLUE), 0);

        w_temp_lbl[i] = lv_label_create(row);
        lv_label_set_text(w_temp_lbl[i], "--\xc2\xb0/--\xc2\xb0");
        lv_obj_set_style_text_font(w_temp_lbl[i], FONT_BODY, 0);
        lv_obj_set_style_text_color(w_temp_lbl[i], lv_color_hex(COL_TEXT), 0);
    }
}

/* Refresh weather card + status bar from live data (called by lv_timer) */
static void weather_update_cb(lv_timer_t *timer)
{
    static const char *wdays[] = { "Sun", "Mon", "Tue", "Wed",
                                   "Thu", "Fri", "Sat" };

    if (dm_weather_fetch(&g_weather) != 0)
        return;

    lv_label_set_text_fmt(w_cur_temp_lbl, "%d\xc2\xb0""C",
                          g_weather.cur_temp);
    lv_label_set_text_fmt(w_cur_desc_lbl, "%s  |  %d%%",
                          dm_wmo_text(g_weather.cur_code),
                          g_weather.cur_humid);

    for (int i = 0; i < g_weather.n_days && i < DM_WEATHER_DAYS; i++) {
        int wd = g_weather.days[i].wday;
        if (wd < 0 || wd > 6)
            wd = 0;
        lv_label_set_text(w_day_lbl[i], wdays[wd]);
        lv_label_set_text(w_icon_lbl[i],
                          dm_wmo_symbol(g_weather.days[i].code));
        lv_obj_set_style_text_color(w_icon_lbl[i],
                                    lv_color_hex(dm_wmo_color(
                                        g_weather.days[i].code)), 0);
        lv_label_set_text_fmt(w_temp_lbl[i], "%d\xc2\xb0 / %d\xc2\xb0",
                              g_weather.days[i].tmax,
                              g_weather.days[i].tmin);
    }

    /* Status bar: live temp + humidity */
    lv_label_set_text_fmt(status_weather_label, "%d\xc2\xb0""C | %d%%",
                          g_weather.cur_temp, g_weather.cur_humid);
}

