/* Weather (live data via dm_weather.c, refreshed by lv_timer) */
static dm_weather_t  g_weather;
static lv_obj_t     *w_cur_temp_lbl;   /* current temp "33°C" */
static lv_obj_t     *w_cur_desc_lbl;   /* "Sunny | AQI 42" */
