/* ================================================================
 * DOCK GLYPHS — hand-drawn white icons on 120×120 canvases.
 * No font, no transform_scale → never clipped, identical on board
 * and simulator. Simple geometric shapes per app index.
 * ================================================================ */

static void cv_fill_rect(lv_obj_t *cv, int x0, int y0, int x1, int y1,
                         uint32_t color)
{
    for (int y = y0; y <= y1; y++)
        for (int x = x0; x <= x1; x++)
            cv_px(cv, x, y, color);
}

static void cv_line_thick(lv_obj_t *cv, int x0, int y0, int x1, int y1,
                          int w, uint32_t color)
{
    for (int i = -w / 2; i <= w / 2; i++)
        cv_line(cv, x0, y0 + i, x1, y1 + i, color);
}

static void cv_ring(lv_obj_t *cv, int cx, int cy, int r_in, int r_out,
                    uint32_t color)
{
    for (int y = cy - r_out; y <= cy + r_out; y++)
        for (int x = cx - r_out; x <= cx + r_out; x++)
            {
                int d2 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
                if (d2 >= r_in * r_in && d2 <= r_out * r_out)
                    cv_px(cv, x, y, color);
            }
}

/* Draw the dock icon for app index i in white on a 120×120 canvas */
static void draw_dock_glyph(lv_obj_t *cv, int i)
{
    const uint32_t W = 0xFFFFFF;

    lv_canvas_fill_bg(cv, lv_color_hex(0x000000), LV_OPA_TRANSP);

    switch (i)
        {
        case 0: /* Music: two eighth notes */
            cv_fill_circle(cv, 38, 84, 10, W);
            cv_fill_rect(cv, 46, 36, 50, 82, W);
            cv_line_thick(cv, 48, 36, 70, 44, 3, W);
            cv_fill_circle(cv, 72, 88, 9, W);
            cv_fill_rect(cv, 80, 48, 84, 86, W);
            cv_line_thick(cv, 82, 48, 104, 56, 3, W);
            break;

        case 1: /* Games: play triangle */
            cv_line_thick(cv, 42, 32, 42, 88, 4, W);
            cv_line_thick(cv, 42, 32, 92, 60, 4, W);
            cv_line_thick(cv, 42, 88, 92, 60, 4, W);
            break;

        case 2: /* Books: open book outline */
            cv_line_thick(cv, 34, 26, 34, 94, 4, W);
            cv_line_thick(cv, 34, 26, 58, 26, 4, W);
            cv_line_thick(cv, 34, 94, 58, 94, 4, W);
            cv_line_thick(cv, 62, 26, 86, 26, 4, W);
            cv_line_thick(cv, 62, 94, 86, 94, 4, W);
            cv_line_thick(cv, 86, 26, 86, 94, 4, W);
            cv_fill_rect(cv, 58, 28, 62, 92, W);   /* spine */
            break;

        case 3: /* Files: folder with tab */
            cv_fill_rect(cv, 28, 38, 92, 88, W);
            cv_fill_rect(cv, 28, 26, 60, 38, W);
            break;

        case 4: /* AI: chat bubble + 3 dots */
            cv_line_thick(cv, 28, 24, 92, 24, 4, W);
            cv_line_thick(cv, 92, 24, 92, 70, 4, W);
            cv_line_thick(cv, 28, 70, 92, 70, 4, W);
            cv_line_thick(cv, 28, 24, 28, 70, 4, W);
            cv_line_thick(cv, 42, 70, 50, 88, 4, W);
            cv_line_thick(cv, 58, 70, 50, 88, 4, W);
            cv_fill_circle(cv, 43, 47, 6, W);
            cv_fill_circle(cv, 60, 47, 6, W);
            cv_fill_circle(cv, 77, 47, 6, W);
