        case 5: /* Settings: gear ring + 8 teeth */
            cv_ring(cv, 60, 60, 16, 30, W);
            cv_fill_rect(cv, 52, 18, 68, 34, W);   /* top */
            cv_fill_rect(cv, 52, 86, 68, 102, W);  /* bottom */
            cv_fill_rect(cv, 18, 52, 34, 68, W);   /* left */
